import useAxiosLarge from "../../hook/useAxiosLarge/useAxiosLarge";

import "./Week.css";

const Week = ({ city }) => {
  const today = new Date().getDate();
  const { dataL } = useAxiosLarge({ city: city });

  return (
    <div>
      {dataL.list.map((elm) =>
        elm.dt_txt.split(" ")[0].split("-")[2] === today ? (
          <p>{elm.dt_txt.split(" ")[0].split("-")[2]}</p>
        ) : null
      )}
      <p>{dataL?.list[0].dt_txt.split(" ")[0].split("-")[2]}</p>
      {/* <p>{day}</p> */}
    </div>
  );
};

export default Week;
